import os
import re
import pandas as pd
from PIL import Image
import pytesseract
import dateutil.parser
from multiprocessing import Pool

def extract_date(text):
    date_patterns = [
        r'\b(\d{1,2})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{4})\b',
        r'\b(\d{4})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{1,2})\b',
        r'\b(\d{1,2})\s+((?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*)\s+(\d{4})\b',
        r'\b(\d{1,2})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{2})\b',
        r'\b(\d{1,2})(\d{2})(\d{4})\b'
    ]

    for idx, pattern in enumerate(date_patterns):
        matches = re.findall(pattern, text, re.IGNORECASE)
        for match in matches:
            part1, part2, part3 = match

            if part2.isdigit() and int(part2) > 12 and '6' in part2:
                part2 = part2.replace('6', '0')

            if part1.isdigit() and int(part1) > 31 and '6' in part1:
                part1 = part1.replace('6', '0')

            date_str = f"{part1}-{part2}-{part3}"
            try:
                if idx == 1:
                    dt = dateutil.parser.parse(date_str, yearfirst=True, dayfirst=False)
                else:
                    dt = dateutil.parser.parse(date_str, dayfirst=True)

                if 2000 <= dt.year <= 2030:
                    return dt.strftime('%Y-%m-%d')
            except:
                pass
    return None

def extract_total(text):
    lines = text.split('\n')
    keywords = [
        ['GRAND TOTAL'],
        ['TOTAL RM', 'TOTAL: RM'],
        ['TOTAL AMOUNT'],
        ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
    ]
    exclusion_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
    ]

    def get_amount(line):
        pattern = r'\b(\d{1,3}(?:,\d{3})*|\d+)\s*[\.,]\s*([0-9oOuU]{2})\b'
        matches = re.findall(pattern, line)
        if matches:
            integer_part, decimal_part = matches[-1]
            integer_part = integer_part.replace(',', '')
            decimal_part = re.sub(r'[oOuU]', '0', decimal_part)
            return f"{integer_part}.{decimal_part}"
        return None

    for kw_group in keywords:
        matched_lines = []
        for i, line in enumerate(lines):
            line_upper = line.upper()
            exclude = False
            for ex in exclusion_keywords:
                if ex in line_upper:
                    exclude = True
                    break
            if exclude:
                continue

            for kw in kw_group:
                if kw in line_upper:
                    matched_lines.append((i, line))
                    break

        for i, line in matched_lines:
            amount = get_amount(line)
            if amount:
                return amount

        for i, line in matched_lines:
            if i + 1 < len(lines):
                amount = get_amount(lines[i+1])
                if amount:
                    return amount

    return None

def process_image(img_name):
    img_dir = '/app/workspace/dataset/img'
    img_path = os.path.join(img_dir, img_name)
    text = pytesseract.image_to_string(Image.open(img_path))

    date_val = extract_date(text)
    total_val = extract_total(text)

    return {'filename': img_name, 'date': date_val, 'total_amount': total_val}

if __name__ == '__main__':
    img_dir = '/app/workspace/dataset/img'
    images = sorted(os.listdir(img_dir))
    with Pool(4) as p:
        results = p.map(process_image, images)

    df = pd.DataFrame(results)
    df.to_excel('/app/workspace/stat_ocr.xlsx', index=False, sheet_name='results')
    print("Extraction complete. Results saved to /app/workspace/stat_ocr.xlsx")
